);

void WppRecorderLogSetIdentifier(
  [in] WPP_RECORDER_LOG RecorderLog,
  [in] PCSTR LogIdentifier
);

typedef enum _WPP_RECORDER_TRI_STATE {
  WppRecorderFalse = FALSE,
  WppRecorderTrue = TRUE,
  WppRecorderUseDefault = 2
} WPP_RECORDER_TRI_STATE, *PWPP_RECORDER_TRI_STATE;

void RECORDER_LOG_CREATE_PARAMS_INIT(
  [out]          PRECORDER_LOG_CREATE_PARAMS Params,
  [in, optional] PCSTR                       LogIdentifier
);

void RECORDER_LOG_CREATE_PARAMS_INIT_APPEND_POINTER(
  [out]          PRECORDER_LOG_CREATE_PARAMS Params,
  [in, optional] PCSTR LogIdentifier,
  [in]           const VOID *LogIdentifierAppendPointer
);

typedef struct _RECORDER_LOG_CREATE_PARAMS {
    ULONG Size;
    ULONG LogTag;
    ULONG TotalBufferSize;
    ULONG ErrorPartitionSize;
} RECORDER_LOG_CREATE_PARAMS, *PRECORDER_LOG_CREATE_PARAMS;

typedef struct _DEBUG_DEVICE_DESCRIPTOR {
  ULONG  Bus;
  ULONG  Slot;
  USHORT Segment;
  USHORT VendorID;
  USHORT DeviceID;
  UCHAR  BaseClass;
  UCHAR  SubClass;
  UCHAR  ProgIf;
  union {
    UCHAR Flags;
    struct {
      UCHAR DbgHalScratchAllocated : 1;
      UCHAR DbgBarsMapped : 1;
      UCHAR DbgScratchAllocated : 1;
      UCHAR DbgUncachedMemory : 1;
    };
  };
} DEBUG_DEVICE_DESCRIPTOR, *PDEBUG_DEVICE_DESCRIPTOR;

typedef struct _FAULT_INFORMATION_ARM64_FLAGS {
  ULONG WriteNotRead : 1;
  ULONG InstructionNotData : 1;
  ULONG Privileged : 1;
  ULONG FaultAddressValid : 1;
  ULONG Reserved : 28;
} FAULT_INFORMATION_ARM64_FLAGS, *PFAULT_INFORMATION_ARM64_FLAGS;

typedef struct _RECORDER_CONFIGURE_PARAMS {
  ULONG                  Size;
  BOOLEAN                CreateDefaultLog;
  WPP_RECORDER_TRI_STATE UseTimeStamp;
} RECORDER_CONFIGURE_PARAMS, *PRECORDER_CONFIGURE_PARAMS;

typedef struct _WPP_TRIAGE_INFO {
  ULONG WppAutoLogHeaderSize;
  ULONG WppDriverContextOffset;
  ULONG WppAutoLogHeaderSizeOffset;
  ULONG WppSizeOfAutoLogHeaderSizeField;
  ULONG WppDriverContextSize;
} WPP_TRIAGE_INFO, *PWPP_TRIAGE_INFO;

typedef struct _DEBUG_TRANSPORT_DATA {
  ULONG   HwContextSize;
  ULONG   SharedVisibleDataSize;
  BOOLEAN UseSerialFraming;
  BOOLEAN ValidUSBCoreId;
  UCHAR   USBCoreId;
} DEBUG_TRANSPORT_DATA, *PDEBUG_TRANSPORT_DATA;

typedef union _MCG_CAP {
  struct {
    ULONG64 CountField : 8;
    ULONG64 ControlMsrPresent : 1;
    ULONG64 ExtendedMsrsPresent : 1;
    ULONG64 SignalingExtensionPresent : 1;
    ULONG64 ThresholdErrorStatusPresent : 1;
    ULONG64 Reserved : 4;
    ULONG64 ExtendedRegisterCount : 8;
    ULONG64 SoftwareErrorRecoverySupported : 1;
    ULONG64 EnhancedMachineCheckCapability : 1;
    ULONG64 ExtendedErrorLogging : 1;
    ULONG64 LocalMachineCheckException : 1;
  } DUMMYSTRUCTNAME;
  ULONG64 QuadPart;
} MCG_CAP, *PMCG_CAP;

NTSYSAPI ULONG DbgPrintEx(
  [in] ULONG ComponentId,
