);

typedef struct _FAULT_INFORMATION {
  FAULT_INFORMATION_ARCH Type;
  BOOLEAN IsStage1;
  union {
    FAULT_INFORMATION_ARM64 Arm64;
  } u;
} FAULT_INFORMATION, *PFAULT_INFORMATION;

typedef struct _KBUGCHECK_REMOVE_PAGES {
  PVOID Context;
